import React from "react";
import { FaBolt, FaUserGraduate, FaLeaf, FaTrophy, FaProjectDiagram, FaCalendarAlt, FaPalette } from "react-icons/fa";

const Projects = () => {
  return (
    <section className="projects">

      {/* HERO - COGNI FLOW */}
      <div className="hero">

        <div className="hero-left">
          <p className="tag">FEATURED PROJECT</p>

          <h1>
            Cogni Flow
          </h1>

          <p className="subtitle">
            A structured cognitive workflow system designed to simplify task flow,
            improve clarity, and enhance productivity through logical UI design.
          </p>

          <div className="stack">
            HTML • CSS • JavaScript
          </div>

          <div className="buttons">
            <button>View Live</button>
            <button>Source Code</button>
          </div>
        </div>

        <div className="hero-right">
          <div className="glow-box">
            <div className="pulse"></div>
            <h2>Flow Engine UI</h2>
          </div>
        </div>

      </div>

      {/* PROJECT SHOWCASE STRIP */}
      <div className="showcase">

        <div className="project">
          <FaBolt />
          <div>
            <h3>EnergyPulse</h3>
            <p>AI smart dashboard for energy monitoring UI system.</p>
          </div>
        </div>

        <div className="project">
          <FaUserGraduate />
          <div>
            <h3>Student Portal</h3>
            <p>Full-stack academic record management system.</p>
          </div>
        </div>

        <div className="project">
          <FaLeaf />
          <div>
            <h3>Farm2Fork</h3>
            <p>Direct farm-to-consumer web marketplace UI.</p>
          </div>
        </div>

      </div>

      {/* ACHIEVEMENTS SIDE TIMELINE */}
      <div className="bottom">

        <div className="timeline">

          <div className="item">
            <FaTrophy />
            <span>SIH Hackathon Semifinalist</span>
          </div>

          <div className="item">
            <FaProjectDiagram />
            <span>Best Project Award (Li-Fi Innovation)</span>
          </div>

          <div className="item">
            <FaCalendarAlt />
            <span>Organized Code Crunch Event</span>
          </div>

          <div className="item">
            <FaPalette />
            <span>Managed Tech & Non-Tech Events</span>
          </div>

        </div>

      </div>

      <style>{`

        .projects {
          min-height: 100vh;
          background: radial-gradient(circle at top, #0b1220, #050816);
          color: white;
          font-family: "Poppins", sans-serif;
          padding: 40px 10%;
        }

        /* HERO */
        .hero {
          display: flex;
          justify-content: space-between;
          align-items: center;
          gap: 60px;
          margin-bottom: 60px;
        }

        .tag {
          color: #38BDF8;
          font-size: 12px;
          letter-spacing: 3px;
        }

        .hero-left h1 {
          font-size: 54px;
          margin: 10px 0;
          color: #e2e8f0;
        }

        .subtitle {
          color: #cbd5e1;
          max-width: 500px;
          line-height: 1.7;
        }

        .stack {
          margin-top: 12px;
          color: #94a3b8;
          font-size: 13px;
        }

        .buttons {
          margin-top: 20px;
          display: flex;
          gap: 12px;
        }

        .buttons button {
          padding: 10px 18px;
          border: none;
          border-radius: 10px;
          cursor: pointer;
          font-weight: 600;
        }

        .buttons button:first-child {
          background: #38BDF8;
          color: #0b1220;
        }

        .buttons button:last-child {
          background: transparent;
          border: 1px solid #38BDF8;
          color: #38BDF8;
        }

        /* RIGHT HERO VISUAL */
        .glow-box {
          width: 260px;
          height: 260px;
          border-radius: 20px;
          background: rgba(56,189,248,0.08);
          border: 1px solid rgba(56,189,248,0.3);
          display: flex;
          align-items: center;
          justify-content: center;
          position: relative;
          overflow: hidden;
        }

        .glow-box h2 {
          color: #38BDF8;
          z-index: 2;
        }

        .pulse {
          position: absolute;
          width: 100%;
          height: 100%;
          background: radial-gradient(circle, rgba(56,189,248,0.2), transparent);
          animation: pulse 3s infinite;
        }

        @keyframes pulse {
          0% { transform: scale(0.9); opacity: 0.4; }
          50% { transform: scale(1.1); opacity: 0.8; }
          100% { transform: scale(0.9); opacity: 0.4; }
        }

        /* SHOWCASE STRIP */
        .showcase {
          display: flex;
          gap: 20px;
          margin-bottom: 60px;
        }

        .project {
          flex: 1;
          padding: 18px;
          border-radius: 14px;
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.15);
          display: flex;
          gap: 12px;
          align-items: flex-start;
        }

        .project svg {
          color: #38BDF8;
          font-size: 20px;
        }

        .project h3 {
          margin: 0;
          color: #38BDF8;
        }

        .project p {
          margin-top: 4px;
          color: #cbd5e1;
          font-size: 13px;
        }

        /* TIMELINE */
        .bottom {
          display: flex;
          justify-content: flex-end;
        }

        .timeline {
          display: flex;
          flex-direction: column;
          gap: 12px;
          width: 350px;
        }

        .item {
          display: flex;
          gap: 10px;
          align-items: center;
          padding: 10px;
          border-left: 3px solid #38BDF8;
          background: rgba(255,255,255,0.03);
          border-radius: 8px;
        }

        .item svg {
          color: #38BDF8;
        }

        .item span {
          color: #cbd5e1;
          font-size: 13px;
        }

        /* RESPONSIVE */
        @media (max-width: 900px) {
          .hero {
            flex-direction: column;
            text-align: center;
          }

          .showcase {
            flex-direction: column;
          }

          .bottom {
            justify-content: center;
          }
        }

      `}</style>

    </section>
  );
};

export default Projects;
